from typing import List
from collections import Counter

class Solution:
    def maxScoreWords(self, words: List[str], letters: List[str], score: List[int]) -> int:
        letter_count = Counter(letters)
        n = len(words)

        def get_word_score_and_counts(word):
            counts = Counter(word)
            s = 0
            for char, count in counts.items():
                idx = ord(char) - ord('a')
                s += count * score[idx]
            return s, counts

        word_info = []
        for word in words:
            w_score, w_counts = get_word_score_and_counts(word)
            word_info.append((word, w_score, w_counts))

        def backtrack(index, current_letters, current_score):
            if index == n:
                return current_score

            res = backtrack(index + 1, current_letters, current_score)

            word, w_score, w_counts = word_info[index]
            can_form = True
            for char, count in w_counts.items():
                if current_letters[char] < count:
                    can_form = False
                    break

            if can_form:
                new_letters = current_letters.copy()
                for char, count in w_counts.items():
                    new_letters[char] -= count
                res = max(res, backtrack(index + 1, new_letters, current_score + w_score))

            return res

        return backtrack(0, letter_count, 0)
